exclusions.text:
/* Hero graph (build_graph_svg.mjs, Storyweave A): edges + arrowheads follow the page text colour so the
   graph reads on the dark (default) and light canvases; the vault chips keep their self-grounding light
   fill + near-black text (set inline). Scoped to #heroGraph — never collides with #vaultsGraph. */
#heroGraph{color:var(--color-text,#c0caf5);}
#heroGraph text{font-family:'Space Grotesk',system-ui,sans-serif;}
#heroGraph .edge{stroke:currentColor;fill:none;stroke-opacity:0.72;}
#heroGraph .edge-arrow{fill:currentColor;stroke:none;fill-opacity:0.82;}
